                        var o=orders[i];if(o.slotPlusOne==0)continue;uint a=ack[i];
                        if((a&0x00ffffffu)!=(uint)o.sequence)continue;
                        alive.Add(o.slotPlusOne);if(receipts.TryGetValue(o.sequence,out var r)){r.ObservedAlive++;if(a==(uint)o.sequence){r.GpuExecutingMembers++;r.Status=LocalOrderStatus.GpuExecuting;}if((a&0x40000000u)!=0)r.GpuBlockedMembers++;}
                    }
                    bool changed=false;
